以下代码中使用了Python 3.10的match语句匹配类，输出是什么？  <pre class="prettyprint lang-py3">from dataclasses import dataclass

@dataclass
class Point:
    x: float
    y: float

def classify(point):
    match point:
        case Point(x=0, y=0):
            return &quot;origin&quot;
        case Point(x=0, y=y):
            return f&quot;y-axis at {y}&quot;
        case Point(x=x, y=0):
            return f&quot;x-axis at {x}&quot;
        case Point(x=x, y=y) if x == y:
            return f&quot;diagonal at {x}&quot;
        case _:
            return &quot;general&quot;

print(classify(Point(3, 3)))</pre>

